:root {
	--ge-panel-color: #ffffff;
	--border-color: #000000;
	--text-color: #000000;
	--toolbar-color: #ffffff;
	--primary-color: #ffffff;
	--dark-text-color: #ffffff;
	--ge-dark-panel-color: #121212;
	--dark-toolbar-color: #121212;
}

.geSidebar *:not(svg *, .mxDisabled, [disabled]),
.geToolbar *:not(svg *, .mxDisabled, [disabled]) {
	opacity: 1 !important;
}

*:not(svg *, .mxDisabled, [disabled], .spinner *, .geBackground, .geDragPreview, .geButton) {
	border-color: light-dark(#000000, #FFFFFF) !important;
}

button, .geBtn, *::-webkit-scrollbar-thumb {
	border-color: light-dark(#000000, #FFFFFF) !important;
	color: light-dark(#000000, #FFFFFF) !important;
}

button, .geBtn {
	border-style: solid !important;
	border-width: 1px !important;
}

.geSimple .geDiagramContainer {
	border-top-style: none !important;
	border-bottom-style: none !important;
}

button:not(:hover), .geBtn:not(:hover) {
	background-color: transparent !important;
}

.gePrimaryBtn {
	border-width: 3px !important;
}

.geActivePage, .geActiveFormatTitle {
	text-decoration: underline;
}

.geActivePage {
	background-color: light-dark(#ffffff, #000000) !important;
	color: inherit !important;
	filter: invert(1);
}

.geBigButton>img:not(.geDarkMode *) {
	filter: invert(1);
}

.geEditor,
.geTitle,
.geFormatTitle  {
	font-size: 15px;
}

.geTab,
.geFormatContainer,
.geSearchSidebar input,
.geSpinnerStatus {
	font-size: 14px !important;
	line-height: 14px !important;
}

.geEditor div.mxTooltip {
	font-size: 12px;
}

.geHint {
	font-size: 11pt;
}

/* Dialogs: restore solid backgrounds and visible borders */
.geDialog {
	background-color: light-dark(#ffffff, var(--ge-dark-panel-color)) !important;
	border: 1px solid light-dark(#000000, #FFFFFF) !important;
	box-shadow: none !important;
}

html body.geDarkMode .geDialog,
html body.geDarkMode div.mxWindow,
html body div.mxWindow.geDarkMode {
	background-color: var(--ge-dark-panel-color) !important;
	border-color: #FFFFFF !important;
	box-shadow: none !important;
}

.geDialog,
html div.mxWindow {
	box-shadow: none !important;
}

/* Dialog overlay: solid opaque background */
.geBackground {
	background-color: light-dark(#ffffff, #000000) !important;
	opacity: 0.9 !important;
	backdrop-filter: none !important;
}

/* Dialog close button: full opacity for visibility */
.geDialog > .geButton {
	opacity: 1 !important;
}

/* Dialog title and footer: solid visible borders */
.geDialogTitle {
	border-bottom: 1px solid light-dark(#000000, #FFFFFF) !important;
}

.geDialogFooter {
	border-top: 1px solid light-dark(#000000, #FFFFFF) !important;
}

/* Input fields: solid visible borders */
.geDialog input[type="text"],
.geDialog input[type="number"],
.geDialog textarea,
.geDialog select {
	border: 1px solid light-dark(#000000, #FFFFFF) !important;
	background-color: light-dark(#ffffff, #000000) !important;
}

:root {
	--ge-panel-color: #f1f3f4;
	--toolbar-color: #f1f3f4;
	--workspace-color: #ececec;
	--dark-toolbar-color: #1e2022;
	--inactive-color: #e4e4e4;
	--active-color: #c4c4c4;
	--primary-color: #c2e7ff;
	--primary-hover-color: #abcfe7;
	--accent-color: #e1e9f7;
	--accent-hover-color: #d8e5f8;
	--accent-text-color: #0b57d0;
	--border-color: #dadada;
	--highlight-color: #e2e2e2;
	--scrollbar-hover-color: #959798;
	--text-color: #3F3F3F;
	--dark-color: #121212;
	--ge-dark-panel-color: #1B1D1E;
	--dark-border-color: #333333;
	--dark-text-color: #C0C0C0;
	--dark-accent-color: #003555;
	--dark-accent-text-color: #52a5f6;
	--dark-active-accent-color: #004A77;
	--dark-inverse-active-color: #c4c4c4;
	--dark-highlight-color: #000000;
	--dark-header-color: #1B1D1E;
	/* Dialogs, windows and comments */
	--dialog-color: #f0f0f0;
	--dark-dialog-color: #2a2a2a;
	--strong-text-color: #1d1d1f;
	--dark-strong-text-color: #e5e5e7;
	--secondary-text-color: #6e6e73;
	--dark-secondary-text-color: #a0a0a0;
	--faint-text-color: #8e8e93;
	--dark-faint-text-color: #7a7a7e;
	/* Input fields, cards and chips */
	--field-color: #ffffff;
	--dark-field-color: #1c1c1e;
	--field-border-color: #d2d2d7;
	--dark-field-border-color: #48484a;
	--strong-border-color: #b9b9be;
	--dark-strong-border-color: #5a5a5e;
	--card-color: #ffffff;
	--dark-card-color: #2c2c2e;
	--soft-color: whitesmoke;
	--dark-soft-color: #3a3a3c;
	--soft-hover-color: #f0f0f2;
	--dark-soft-hover-color: #3a3a3c;
	/* Accents (selected and focused states) */
	--focus-color: #0071e3;
	--dark-focus-color: #0a84ff;
	--mention-color: #0a4bb0;
	--dark-mention-color: #7eb1ff;
	--mention-background-color: #e8f0fe;
	--dark-mention-background-color: #10325f;
	--selected-color: #d4e4f7;
	--selected-hover-color: #c4d8f0;
	--active-item-color: lightgray;
	--dark-active-item-color: darkgray;
	/* Status */
	--error-color: #b62623;
	--dark-error-color: #ffffff;
	--error-background-color: #eacccc;
	--dark-error-background-color: #a20025;
	/* Misc */
	--scrollbar-color: #e2e2e2;
	--dark-scrollbar-color: #2c2c2c;
	--prop-stripe-color: #fcfcfc;
	--prop-accent-color: #D9E1F2;
	--prop-accent-text-color: #305496;
}

.geEditor * {
	forced-color-adjust: none;
}

.geEditor {
	font-family: -apple-system, BlinkMacSystemFont, "Segoe UI Variable", "Segoe UI", system-ui, ui-sans-serif, Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji";
	color-scheme: light dark;
	position: absolute;
	overflow: hidden;
	font-size: 14px;
	width: 100%;
	height: 100%;
	margin: 0;
	display: grid;
	grid-template-rows: min-content min-content 1fr min-content;
	grid-template-columns: min-content min-content 1fr min-content;
}

html:has(.geFullscreen),
.geEditor,
.mxWindow,
.geDialogTitle,
.geShapePicker,
.geDialogFooter,
.geSidebarTooltip {
	background-color: light-dark(var(--ge-panel-color), var(--ge-dark-panel-color));
}

.geEditor>svg,
div[id*="dgeMermaidOutput-"] {
	position: absolute;
	margin: -9999px 0 0 -9999px;
	z-index: -1;
}

.geEditor>#geInfo {
	grid-column: 1 / -1;
	grid-row: 1 / -1;
}

.geSimpleMainMenu,
.geEditor>.geMenubarContainer {
	grid-column: 1 / -1;
	grid-row: 1;
	width: 100%;
	height: 60px;
	margin-top: 4px;
}

.geCompactMode .geAppIcon,
.geCompactMode .geFilenameContainer,
.geSimple .geMenubarContainer:not(.geMinimal *),
.geCompactMode .geButtonContainer:not(.geAtlas *, .geEmbed *),
.geSimple>.geToolbarContainer:not(.geSimpleMainMenu, .geSketch *),
.geSketch>.geToolbarContainer:has(.geToolbar) {
	display: none;
}

.geEditor.geAtlas>.geMenubarContainer,
.geEditor.geCompactMode>.geMenubarContainer {
	margin-top: 0;
	height: 30px;
}

.geEditor.geCompactMode>.geToolbarContainer:not(.geSketch *, .geAtlas *) {
	padding-left: 8px;
}

.geEditor.geSimple>.geToolbarContainer:not(.geVerticalToolbar) {
	padding: 0 10px;
	height: 50px;
}

.geEditor.geSketch>.geToolbarContainer:not(.geVerticalToolbar) {
	height: 44px;
}

.geSketchMainMenu {
	left: 10px;
	top: 10px;
}

.geEditor:not(.geSimple) .geSimpleMainMenu {
	display: none;
